export type GetChildOverviewQueryResult = NonNullable<
  Awaited<ReturnType<typeof getChildOverview>>
>;
export type GetChildOverviewQueryError = ErrorType<unknown>;

/**
 * @summary Get child dashboard overview (alerts + devices summary)
 */

export function useGetChildOverview<
  TData = Awaited<ReturnType<typeof getChildOverview>>,
  TError = ErrorType<unknown>,
>(
  childId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getChildOverview>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetChildOverviewQueryOptions(childId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
